#!/usr/bin/env bash
# -----------------------------------------------------------------------------
# GENERATED by micro-os-scaffold. Run selected CTest cases for one configuration.
#
#   tests/test.sh [configuration] [selection-id ...] [--hwd] [--regex <re>]
#
# Examples:
#   ./test.sh <config> 4.4.11
#   ./test.sh <config> 4.4.12
#   ./test.sh <config> 4.4.11 4.4.12
#
# Selection ids run exactly the CTest cases listed for them in
# scripts/selected-tests.txt. --regex is only for ad-hoc filtering.
# -----------------------------------------------------------------------------
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$HERE/scripts/env.sh"
DEFAULT_CONFIG='__DEFAULT_CONFIG__'
CONFIG=""
SELECTIONS=()
LABELS=(-LE hwd)
EXTRA=()
REGEX_GIVEN=0
HWD=0
while [[ $# -gt 0 ]]; do
  case "$1" in
    --hwd) LABELS=(); HWD=1 ;;
    --regex) EXTRA=(-R "$2"); REGEX_GIVEN=1; shift ;;
    -*) echo "Unknown option: $1" >&2; exit 2 ;;
    *)
      if [[ "$1" =~ ^[0-9]+(\.[0-9]+)+$ ]]; then
        SELECTIONS+=("$1")
      else
        CONFIG="$1"
      fi
      ;;
  esac
  shift
done
CONFIG="${CONFIG:-$DEFAULT_CONFIG}"
BUILD_DIR="$HERE/build/$CONFIG"
[[ -d "$BUILD_DIR" ]] || { echo "No build tree: $BUILD_DIR (run tests/build.sh $CONFIG)" >&2; exit 2; }

if [[ "$REGEX_GIVEN" == "0" && -f "$HERE/scripts/selected-tests.txt" ]]; then
  # selected-tests.txt: configuration <TAB> selection-id <TAB> ctest-name[,ctest-name...]
  if [[ ${#SELECTIONS[@]} -gt 0 ]]; then
    ROWS=()
    for id in "${SELECTIONS[@]}"; do
      while IFS= read -r row; do ROWS+=("$row"); done < <(
        awk -F "\t" -v c="$CONFIG" -v s="$id" '!/^#/ && $1 == c && $2 == s { print $3 }' \
          "$HERE/scripts/selected-tests.txt"
      )
      [[ ${#ROWS[@]} -gt 0 ]] || { echo "No selected test ${id} for ${CONFIG}" >&2; exit 2; }
    done
  else
    ROWS=()
    while IFS= read -r row; do ROWS+=("$row"); done < <(
      awk -F "\t" -v c="$CONFIG" '!/^#/ && $1 == c { print $3 }' \
        "$HERE/scripts/selected-tests.txt"
    )
  fi

  ALL_NAMES=()
  for row in "${ROWS[@]}"; do
    IFS=',' read -r -a parts <<< "$row"
    for name in "${parts[@]}"; do
      [[ -n "$name" ]] || continue
      ALL_NAMES+=("$name")
    done
  done

  NAMES=()
  if [[ "$HWD" == "1" ]]; then
    NAMES=("${ALL_NAMES[@]}")
  else
    for name in "${ALL_NAMES[@]}"; do
      [[ "$name" == *-hwd ]] && continue
      NAMES+=("$name")
    done
    # A selection whose only image is hardware still runs without --hwd.
    [[ ${#NAMES[@]} -gt 0 ]] || NAMES=("${ALL_NAMES[@]}")
  fi

  if [[ ${#NAMES[@]} -gt 0 ]]; then
    LABELS=()
    IFS='|'
    COMBINED="^(${NAMES[*]})$"
    unset IFS
    EXTRA=(-R "$COMBINED")
    echo "Selected tests: ${#NAMES[@]} from scaffold.json"
  elif [[ ${#SELECTIONS[@]} -eq 0 ]]; then
    echo "No selected tests for ${CONFIG} (hardware tests need --hwd)." >&2
    exit 2
  fi
fi

exec ctest --test-dir "$BUILD_DIR" -V "${LABELS[@]}" "${EXTRA[@]}"
